import sys, json
sys.path.insert(0, '/home/user/kitayskiy-5/dev/tests')
import d13tool as T
W = [  # hz, py (слоги через точку), ru, урок, страница тетради, rr
 ('早上', 'zǎo.shang', 'утро', 1, 7, 'цзао-шан'), ('晚上', 'wǎn.shang', 'вечер', 1, 7, 'вань-шан'),
 ('明天', 'míng.tiān', 'завтра', 3, 14, 'мин-тянь'), ('再见', 'zài.jiàn', 'до свидания', 3, 12, 'цзай-цзянь'), ('没事', 'méi.shì', 'ничего страшного; всё в порядке', 3, 15, 'мэй-ши'),
 ('文具', 'wén.jù', 'канцелярские принадлежности', 5, 24, 'вэнь-цзюй'), ('对', 'duì', 'верно, правильно', 5, 24, 'дуй'), ('谁的', 'shéi.de', 'чей', 5, 24, 'шэй-дэ'),
 ('橡皮', 'xiàng.pí', 'ластик', 5, 24, 'сян-пи'), ('钱包', 'qián.bāo', 'кошелёк', 5, 44, 'цянь-бао'), ('铅笔', 'qiān.bǐ', 'карандаш', 5, 54, 'цянь-би'), ('手机', 'shǒu.jī', 'мобильный телефон', 5, 44, 'шоу-цзи'),
 ('网球', 'wǎng.qiú', 'теннис', 6, 29, 'ван-цю'), ('冰球', 'bīng.qiú', 'хоккей', 6, 29, 'бин-цю'), ('棒球', 'bàng.qiú', 'бейсбол', 6, 29, 'бан-цю'), ('排球', 'pái.qiú', 'волейбол', 6, 29, 'пай-цю'), ('乒乓球', 'pīng.pāng.qiú', 'настольный теннис', 6, 30, 'пин-пан-цю'),
 ('日语', 'Rì.yǔ', 'японский язык', 7, 34, 'жи-юй'), ('书包', 'shū.bāo', 'портфель, школьный рюкзак', 7, 34, 'шу-бао'), ('眼镜', 'yǎn.jìng', 'очки', 7, 34, 'янь-цзин'),
 ('纸', 'zhǐ', 'бумага', 8, 38, 'чжи'), ('照片', 'zhào.piàn', 'фотография', 8, 38, 'чжао-пянь'), ('文件夹', 'wén.jiàn.jiā', 'папка для файлов', 8, 38, 'вэнь-цзянь-цзя'), ('鼠标', 'shǔ.biāo', 'компьютерная мышь', 8, 38, 'шу-бяо'),
 ('电话', 'diàn.huà', 'телефон', 8, 38, 'дянь-хуа'), ('号码', 'hào.mǎ', 'номер', 8, 38, 'хао-ма'), ('电话号码', 'diàn.huà.hào.mǎ', 'номер телефона', 8, 44, 'дянь-хуа хао-ма'),
 ('巧克力', 'qiǎo.kè.lì', 'шоколад', 10, 49, 'цяо-кэ-ли'), ('新', 'xīn', 'новый', 10, 49, 'синь'), ('爱', 'ài', 'любить', 10, 49, 'ай'),
 ('对不起', 'duì.bu.qǐ', 'извините, простите', 13, 64, 'дуй-бу-ци'),
]
s, a, b, D = T.load()
have = {w['hz'] for w in D['words']}
n = max(int(w['id'][1:]) for w in D['words']) + 1
for hz, py, ru, L, pg, rr in W:
    if hz in have: continue
    D['words'].append({'hz': hz, 'py': py, 'ru': ru, 'L': L, 'kind': 'word', 'id': 'w%03d' % n, 'syl': py.split('.'), 'disp': py.replace('.', ''), 'culture': False, 'core': False, 'T': [], 'rr': rr,
        'src': 'Рабочая тетрадь, с. %d' % pg, 'note': 'Дополнительная лексика из рабочей тетради. Перевод и чтение по-русски написаны составителем сайта (в тетради перевод почти не дан).'})
    n += 1
T.save(s, a, b, D); print('добавлено', n - 213, 'слов; всего D13.words', len(D['words']))
